"""Small bilingual view of the shared health scoring API."""
HEALTH_PAGE = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>网络健康 / Network Health</title>
<style>
body{font:15px system-ui,sans-serif;background:#f3f6fb;color:#182d46;margin:0}main{max-width:1120px;margin:32px auto;padding:0 20px}header{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}h1{font-size:28px}h2{font-size:18px}select,button{padding:9px;border:1px solid #aebdd0;border-radius:7px;background:white}button{cursor:pointer;color:#174d8e}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px;margin:24px 0}.card,details,.notice{background:white;border:1px solid #ccd7e6;border-radius:12px;padding:20px}.number{font-size:42px;font-weight:700;display:block;margin-top:8px}.muted{color:#536780;line-height:1.7}.notice{border-left:5px solid #347bb7}details{margin:12px 0}summary{cursor:pointer;font-weight:650;line-height:1.7}table{width:100%;border-collapse:collapse;margin-top:14px}th,td{text-align:left;border-bottom:1px solid #dce4ef;padding:12px 8px;vertical-align:top}.scroll{overflow-x:auto}.bad{color:#b53e29}.good{color:#177852}a{color:#125b9d}#error{color:#ad361e}small{font-weight:400}#inventory{margin:12px 0}
</style></head><body><main><header><h1 id="title"></h1><div><select id="language"><option value="zh">中文</option><option value="en">English</option></select> <select id="site"></select> <button id="refresh"></button></div></header><p id="intro" class="muted"></p><div id="inventory" class="muted"></div><div id="error"></div><div class="cards" id="cards"></div><div class="notice" id="method"></div><h2 id="detailTitle"></h2><div id="devices"></div><p class="muted" id="limits"></p><p><a href="http://192.168.20.169:3000/d/eve-aiops-report">Grafana 中文汇报</a> · <a href="http://192.168.20.169:3000/d/eve-aiops-report-en">English report</a> · <a href="/tools">Path</a></p></main><script>
const $=id=>document.getElementById(id), tr=(zh,en)=>$('language').value==='en'?en:zh;
const labels={collection:['采集可用性','Collection availability'],interfaces:['已确认链路端口','Confirmed link ports'],cpu:['CPU','CPU'],memory:['内存','Memory'],bgp:['BGP','BGP'],ospf:['OSPF','OSPF'],overlay:['Overlay 邻居','Overlay peers'],power:['电源','Power'],module:['模块','Modules']};
const reasons={baseline_invalid:['BGP 基线格式、设备标识或审批信息无效','Invalid BGP baseline schema, identity or approval'],baseline_not_applicable:['已确认 BGP 不适用，排除评分','Approved: BGP not applicable; excluded'],baseline_incomplete:['BGP 已启用，但缺少必需邻居基线','BGP enabled but required peers are undefined'],baseline_evidence_missing:['BGP 基线已加载，但完整邻居数据不可用或过期','BGP baseline loaded; complete peer evidence unavailable or stale'],approved_bgp_baseline:['按 Nautobot 已确认 BGP 基线评估','Assessed against approved Nautobot BGP baseline'],collected:['采集成功','Collected'],collection_failed:['采集失败，不等于设备离线','Collection failed; does not establish unreachability'],stale_or_missing:['数据过期或缺失','Stale or missing observations'],confirmed_ports:['只评估已确认连线的端口','Only confirmed connected ports'],no_confirmed_ports:['缺少有效的已确认连线','No fresh confirmed cabling'],dataset_failed:['对应数据集不可用','Dataset unavailable'],utilization:['当前利用率','Current utilization'],missing:['缺少有效数值','Valid value unavailable'],not_collected_for_platform:['该平台暂未采集，排除在评分范围外','Not collected for this platform; outside scoring scope'],observed_neighbors:['已观察邻居状态','Observed peer states'],no_observed_neighbors:['本轮未观察到邻居，排除；不代表配置已验证','No peers observed; excluded, not configuration validation'],component_state:['已识别的部件状态','Recognized component states']};
function detailText(d){
 if(d.percent!==undefined)return d.percent+'%';
 const states={oper_down:['链路 Down','Link down'],unknown:['未知','Unknown'],administratively_disabled:['管理员关闭，已排除','Administratively disabled; excluded'],neighbor_down:['邻居未就绪','Peer not ready']};
 if(d.interface)return d.interface+': '+tr(...(states[d.reason]||[d.reason,d.reason]));
 if(d.neighbor){const status={...states,baseline_neighbor_healthy:['正常','Healthy'],baseline_neighbor_missing:['预期邻居缺失','Expected peer missing'],baseline_as_mismatch:['对端 AS 与基线不符','Peer AS differs from baseline']};return d.neighbor+' ('+d.context+(d.afi_safi?' / '+d.afi_safi:'')+'): '+tr(...(status[d.reason]||[d.reason,d.reason]));}
 if(d.component)return d.component+': '+d.status;
 return '';
}
let payload,inventory;
function cell(row,text,tag='td'){const n=document.createElement(tag);n.textContent=text;row.append(n);return n;}
function render(){
 $('title').textContent=tr('网络健康评分','Network health score');$('refresh').textContent=tr('刷新','Refresh');$('intro').textContent=tr('100 分为最高。将已发现问题与缺失证据分开，避免把“没有数据”当作健康。','100 is the maximum. Observed problems and missing evidence are shown separately.');
 $('detailTitle').textContent=tr('设备明细 · 低分优先','Device details · lowest score first');
 if(!payload)return;
 $('inventory').textContent=tr('运行清单源：','Active inventory source: ')+(inventory?.effective_source||'unknown')+' · '+tr('设备数：','Devices: ')+(inventory?.device_count??'—')+' · '+tr('评分时间：','Scored at: ')+new Date(payload.observed_at).toLocaleString();
 $('cards').replaceChildren();
 for(const [title,value] of [[tr('健康评估分 / 100','Health points / 100'),payload.score],[tr('证据覆盖率 %','Evidence coverage %'),payload.coverage_percent],[tr('已观察问题扣分','Observed deductions'),payload.deduction_points],[tr('缺证暂未获得分数','Unassessed points'),payload.unassessed_points]]){const n=document.createElement('div');n.className='card';n.textContent=title;const v=document.createElement('span');v.className='number';v.textContent=value==null?'—':value.toFixed(1);n.append(v);$('cards').append(n);}
 $('method').textContent=tr('评分 v1：采集 40%、已确认接口 20%、CPU/内存各 10%、协议邻居 10%、电源/模块 10%。排除项重新分配权重。缺证部分暂不计分，不表示故障。全网按设备等权平均；覆盖率不足时结果为暂定，需展开明细查看原因。','Score v1: collection 40%, confirmed ports 20%, CPU/memory 10% each, peers 10%, power/modules 10%. Excluded checks redistribute their weights. Missing evidence earns no points but is not a fault. Devices have equal weight. Partial coverage produces a provisional score; expand a device for details.');
 $('devices').replaceChildren();
 for(const d of [...payload.devices].sort((a,b)=>a.score-b.score)){
 const box=document.createElement('details'),summary=document.createElement('summary');summary.textContent=d.device+' · '+d.site+' · '+d.score.toFixed(1)+'/100 · '+tr('覆盖率 ','Coverage ')+d.coverage_percent.toFixed(1)+'%';box.append(summary);
 const scroll=document.createElement('div');scroll.className='scroll';const table=document.createElement('table');const head=document.createElement('tr');for(const t of [tr('检查项','Check'),tr('基础权重','Base weight'),tr('问题扣分','Deductions'),tr('缺证分数','Unassessed'),tr('说明','Evidence')])cell(head,t,'th');table.append(head);
 for(const c of d.checks){const r=document.createElement('tr');cell(r,tr(...labels[c.key]));cell(r,c.excluded?tr('排除','Excluded'):c.weight);cell(r,c.deduction_points);cell(r,c.unassessed_points);cell(r,tr(...(reasons[c.reason]||[c.reason,c.reason]))+(c.details.length?' · '+c.details.map(detailText).join('; '):''));table.append(r);}scroll.append(table);box.append(scroll);$('devices').append(box);
 }
 for(const d of payload.excluded_devices||[]){const box=document.createElement('div');box.className='card';box.textContent=d.device+' · '+tr('已排除评分','Excluded from health')+' · '+d.status+' · '+(d.exclusion_reason||d.exclusion_code||'')+(d.exclusion_owner?' · '+d.exclusion_owner:'')+(d.exclusion_until?' · '+d.exclusion_until:'');$('devices').append(box);}
 $('inventory').textContent+=' · '+tr('参与评分 / 排除：','Included / excluded: ')+payload.device_count+' / '+(payload.excluded_count||0);
 $('limits').textContent=tr('范围：仅评估当前已采集指标，不等于业务 SLA 或实际报文验证。v1 未纳入时延/丢包、带宽拥塞、错误计数增量、应用探测和安全威胁。未观察到邻居不等于协议配置正确；已确认的 BGP 基线用于识别缺失邻居；未配置基线的协议仍按观察结果评估。页面手动刷新。','Scope: current collected metrics, not a business SLA or packet-delivery proof. v1 excludes latency/loss, bandwidth saturation, error-counter deltas, application probes and threats. Empty peer tables do not verify protocol configuration; approved BGP baselines detect missing peers; protocols without baselines remain observation-based. Manual refresh.');
}
async function load(){ $('error').textContent='';$('refresh').disabled=true;try{const r=await fetch('/api/health/score?site='+encodeURIComponent($('site').value||'all'));if(!r.ok)throw Error(r.status);payload=await r.json();render();}catch(e){$('error').textContent=tr('加载失败：','Load failed: ')+e.message;}finally{$('refresh').disabled=false;}}
$('language').value=new URLSearchParams(location.search).get('lang')==='en'?'en':'zh';$('language').onchange=render;$('site').onchange=load;$('refresh').onclick=load;
(async()=>{try{const [i,o]=await Promise.all([fetch('/api/inventory/status').then(r=>r.json()),fetch('/tools/options').then(r=>r.json())]);inventory=i;for(const site of ['all',...o.sites]){const n=document.createElement('option');n.value=site;n.textContent=site;$('site').append(n);}$('site').value=new URLSearchParams(location.search).get('site')||'all';if(!$('site').value)$('site').value='all';}catch(e){$('error').textContent=e.message;}render();await load();})();
</script></body></html>'''
